-- The 8 topics people pick when they join, approved by the owner on 16 Oct 2026, and the
-- tags that link every sermon with a transcript to one to three of them. See
-- supabase/migrations/20261016000300_topics.sql for how sermons are tagged.
--
-- Topics were picked by gpt-5.4-mini from the needs, the paths and 600 sermon titles, with every
-- need and path required to appear in some topic; labels were tidied by hand. match_text keeps the
-- working label the vectors were made from (text-embedding-3-large, 768 dimensions).
--
-- Re-running replaces the topics and re-tags every sermon: the catalogue's mean and spread are
-- measured again, so scores stay on one scale.

begin;

delete from public.topics;

insert into public.topics (id, label, description, need_ids, path_ids, sort) values
