-- Each topic's mean and spread across the catalogue (every sermon with passages).
with c as (
  select youtube_id, avg(embedding::extensions.vector(768)) as v
  from public.passages
  where dup_of is null and not coalesce(hidden_from_search, false)
  group by youtube_id
),
s as (
  select tv.topic_id,
    avg(1 - (c.v operator(extensions.<=>) tv.embedding::extensions.vector(768))) as m,
    stddev_pop(1 - (c.v operator(extensions.<=>) tv.embedding::extensions.vector(768))) as sd
  from c cross join public.topic_vectors tv
  group by tv.topic_id
)
update public.topic_vectors tv set mean = s.m, sd = s.sd
from s where s.topic_id = tv.topic_id;

select public.tag_sermon_topics() as sermons_tagged;

commit;
